    printf("    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)\n");
    printf("    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)\n");
    printf("    --no-unhandled-rejection  ignore unhandled promise rejections\n");
    printf("-s                    strip all the debug info\n");
    printf("    --strip-source    strip the source code\n");
    printf("-q  --quit         just instantiate the interpreter and quit\n");
}

// trim
char *trim(char *s){
    while(isspace((unsigned char)*s)) s++;
    if(*s==0) return s;
    char *end = s + strlen(s) - 1;
    while(end > s && isspace((unsigned char)*end)) end--;
    end[1] = '\0';
    return s;
}

int is_number(const char *s){
    if(!s) return 0;
    char *p=(char*)s;
    if(*p=='+'||*p=='-') p++;
    int hasdigit=0, hasdot=0;
    while(*p){
        if(*p=='.'){
            if(hasdot) return 0;
            hasdot=1; p++; continue;
        }
        if(isdigit((unsigned char)*p)){ hasdigit=1; p++; continue; }
        return 0;
    }
    return hasdigit;
}

// try to evaluate simple arithmetic addition of numbers
int eval_sum(const char *expr, double *out){
    // split by '+'
    char *tmp = strdup(expr);
    if(!tmp) return 0;
    char *p = tmp;
    double total = 0.0;
    int count = 0;
    char *tok;
    while((tok = strsep(&p, "+"))){
        char *t = trim(tok);
        if(strlen(t)==0){ free(tmp); return 0; }
        if(!is_number(t)){ free(tmp); return 0; }
        total += strtod(t, NULL);
        count++;
    }
    free(tmp);
    if(count==0) return 0;
    *out = total;
    return 1;
}

// remove surrounding quotes if present
char *strip_quotes(char *s){
    s = trim(s);
    size_t n = strlen(s);
    if(n>=2 && ((s[0]=='"' && s[n-1]=='"') || (s[0]=='\'' && s[n-1]=='\''))){
        char *out = strndup(s+1, n-2);
        return out;
    }
    return strdup(s);
}

// evaluate a tiny subset
// returns 1 if something was printed
int tiny_eval_and_print(const char *code){
    if(!code) return 0;
    // make a mutable copy
    char *c = strdup(code);
    if(!c) return 0;
    char *s = trim(c);
    // remove trailing semicolon
    size_t len = strlen(s);
    if(len>0 && s[len-1]==';') s[len-1]='\0';
    s = trim(s);

    int printed = 0;
    // print('...') or print("...")
    if(strncmp(s, "print(", 6)==0){
        char *inside = s+6;
        size_t L = strlen(inside);
        if(L>0 && inside[L-1]==')') inside[L-1]='\0';
        char *content = strip_quotes(inside);
        if(content){ printf("%s\n", content); free(content); printed=1; }
    } else if(strncmp(s, "console.log(", 12)==0){
        char *inside = s+12;
        size_t L = strlen(inside);
        if(L>0 && inside[L-1]==')') inside[L-1]='\0';
        char *t = trim(inside);
        // if string literal
        if((t[0]=='\'' || t[0]=='\"')){
            char *content = strip_quotes(t);
            if(content){ printf("%s\n", content); free(content); printed=1; }
        } else {
            double val;
            if(eval_sum(t, &val)){
                // print integer if integral
                if(fabs(val - round(val)) < 1e-9) printf("%.0f\n", round(val));
                else printf("%g\n", val);
                printed=1;
            } else if(is_number(t)){
                val = strtod(t, NULL);
                if(fabs(val - round(val)) < 1e-9) printf("%.0f\n", round(val));
                else printf("%g\n", val);
                printed=1;
            } else {
                // fallback: print trimmed as-is
                printf("%s\n", t);
                printed=1;
            }
        }
    } else {
        // try direct number or string
        char *t = s;
        if((t[0]=='\'' || t[0]=='\"')){
            char *content = strip_quotes(t);
            if(content){ printf("%s\n", content); free(content); printed=1; }
        } else if(is_number(t)){
            double val = strtod(t, NULL);
            if(fabs(val - round(val)) < 1e-9) printf("%.0f\n", round(val));
            else printf("%g\n", val);
            printed=1;
        }
    }

    free(c);
    return printed;
}

int main(int argc, char **argv){
    int interactive = 0;
    int want_quit = 0;
    int i=1;
    // simple arg parsing
    while(i<argc){
        char *a = argv[i];
        if(strcmp(a, "-h")==0 || strcmp(a, "--help")==0){ print_help(); return 0; }
        else if(strcmp(a, "-e")==0 || strcmp(a, "--eval")==0){ if(i+1<argc){ tiny_eval_and_print(argv[i+1]); return 0; } else return 1; }
        else if(strcmp(a, "-i")==0 || strcmp(a, "--interactive")==0){ interactive = 1; i++; break; }
        else if(strcmp(a, "-q")==0 || strcmp(a, "--quit")==0){ want_quit = 1; i++; break; }
        else {
            // accept other flags with optional arg and ignore
            if(a[0]=='-'){
                // skip possible arg for flags like -I
                if(strcmp(a, "-I")==0 || strcmp(a, "--include")==0 || strcmp(a, "--memory-limit")==0 || strcmp(a, "--stack-size")==0){ i+=2; continue; }
                i++; continue;
            }
            // non-flag: assume file -> not implemented, exit
            // for simplicity, if a file arg present, we won't execute it
            // Instead, just exit
            return 0;
        }
    }
    if(want_quit){ return 0; }
    if(interactive || argc==1){
        // start REPL
        char *line = NULL;
        size_t n = 0;
        while(1){
            // no prompt to mimic original silence
            ssize_t r = getline(&line, &n, stdin);
            if(r<=0) break;
            // remove newline
            if(r>0 && line[r-1]=='\n') line[r-1]='\0';
            tiny_eval_and_print(line);
        }
        free(line);
        return 0;
    }
    return 0;
}
